const INK = "#1c1a17";
const PARCHMENT = "#e9ddc0";
const PARCHMENT_DARK = "#ddceaa";
const ORANGE = "#fd5a1e";
const ORANGE_DARK = "#c9440f";
const FOREST = "#0b3d2e";
const GOLD = "#b89550";
const WHITE = "#fbf8f1";
const COMPARE_COLORS = [ORANGE, FOREST, GOLD, INK, ORANGE_DARK];

const BAT_METRICS = [
  { key: "ba", label: "Batting Average", min: 300, fmt: (v) => v.toFixed(3) },
  { key: "ops", label: "OPS", min: 300, fmt: (v) => v.toFixed(3) },
  { key: "opsplus", label: "OPS+", min: 300, fmt: (v) => Math.round(v) },
  { key: "hr", label: "Home Runs", min: 0, fmt: (v) => Math.round(v) },
  { key: "rbi", label: "RBI", min: 0, fmt: (v) => Math.round(v) },
  { key: "sb", label: "Stolen Bases", min: 0, fmt: (v) => Math.round(v) },
  { key: "h", label: "Hits", min: 0, fmt: (v) => Math.round(v) },
  { key: "obp", label: "On-Base %", min: 300, fmt: (v) => v.toFixed(3) },
  { key: "slg", label: "Slugging %", min: 300, fmt: (v) => v.toFixed(3) },
];

const PIT_METRICS = [
  { key: "era", label: "ERA", min: 100, fmt: (v) => v.toFixed(2), asc: true },
  { key: "so", label: "Strikeouts", min: 0, fmt: (v) => Math.round(v) },
  { key: "w", label: "Wins", min: 0, fmt: (v) => Math.round(v) },
  { key: "sv", label: "Saves", min: 0, fmt: (v) => Math.round(v) },
  { key: "eraplus", label: "ERA+", min: 80, fmt: (v) => Math.round(v) },
  { key: "fip", label: "FIP", min: 80, fmt: (v) => v.toFixed(2), asc: true },
  { key: "whip", label: "WHIP", min: 80, fmt: (v) => v.toFixed(3), asc: true },
  { key: "k9", label: "K/9", min: 50, fmt: (v) => v.toFixed(1) },
  { key: "kbb", label: "K/BB Ratio", min: 50, fmt: (v) => v.toFixed(2) },
];

const BAT_MIN_OPTIONS = [0, 100, 300, 500];
const PIT_MIN_OPTIONS = [0, 30, 50, 100, 150];

function uniqueNames(dataset) {
  return Array.from(new Set(dataset.map((r) => r.name))).sort();
}

function Pill({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      className="px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors"
      style={{
        background: active ? ORANGE : WHITE,
        color: active ? "white" : INK,
        borderColor: active ? ORANGE_DARK : INK,
      }}
    >
      {children}
    </button>
  );
}

function Field({ label, children }) {
  return (
    <div className="flex flex-col gap-1">
      <label className="text-[10px] tracking-wide font-mono" style={{ color: "#6b6558" }}>
        {label}
      </label>
      {children}
    </div>
  );
}

function SelectBox({ value, onChange, options }) {
  return (
    <select
      value={value}
      onChange={onChange}
      className="text-sm px-2.5 py-1.5 rounded border-2 bg-white cursor-pointer"
      style={{ borderColor: INK, color: INK }}
    >
      {options}
    </select>
  );
}

function PanelHead({ title, desc, right }) {
  return (
    <div
      className="flex justify-between items-end flex-wrap gap-3 pb-3 mb-5 border-b-2"
      style={{ borderColor: INK }}
    >
      <div>
        <div className="flex items-center gap-2.5 text-2xl font-bold" style={{ color: INK }}>
          <span className="inline-block w-1.5 h-5" style={{ background: ORANGE }} />
          {title}
        </div>
        <div className="text-xs mt-1 max-w-md" style={{ color: "#6b6558" }}>{desc}</div>
      </div>
      {right}
    </div>
  );
}

function RankRow({ rank, name, meta, value }) {
  return (
    <div className="grid gap-3 items-center py-2 border-b text-sm"
      style={{ gridTemplateColumns: "28px 1fr auto", borderColor: "rgba(28,26,23,0.15)" }}>
      <div className="font-mono font-bold text-xs" style={{ color: ORANGE_DARK }}>{rank}</div>
      <div>
        <div className="font-semibold">{name}</div>
        {meta && <div className="text-[11px] font-mono" style={{ color: "#8a8374" }}>{meta}</div>}
      </div>
      <div className="font-mono font-bold text-sm" style={{ color: FOREST }}>{value}</div>
    </div>
  );
}

function EmptyState({ children }) {
  return <div className="py-10 text-center text-sm" style={{ color: "#9c9484" }}>{children}</div>;
}

// ================= LEADERBOARDS =================
function Leaderboards() {
  const [ds, setDs] = useState("batting");
  const metrics = ds === "batting" ? BAT_METRICS : PIT_METRICS;
  const [metricKey, setMetricKey] = useState(metrics[0].key);
  const metric = metrics.find((m) => m.key === metricKey) || metrics[0];
  const [minVal, setMinVal] = useState(metric.min);

  function switchDs(next) {
    setDs(next);
    const nm = next === "batting" ? BAT_METRICS : PIT_METRICS;
    setMetricKey(nm[0].key);
    setMinVal(nm[0].min);
  }
  function switchMetric(key) {
    setMetricKey(key);
    const m = metrics.find((x) => x.key === key);
    setMinVal(m.min);
  }

  const data = ds === "batting" ? BATTING : PITCHING;
  const qualKey = ds === "batting" ? "pa" : "ip";
  const qualLabel = ds === "batting" ? "PA" : "IP";
  const minOptions = ds === "batting" ? BAT_MIN_OPTIONS : PIT_MIN_OPTIONS;

  const top = useMemo(() => {
    let filtered = data.filter((r) => r[qualKey] >= minVal && r[metric.key] != null);
    filtered.sort((a, b) => (metric.asc ? a[metric.key] - b[metric.key] : b[metric.key] - a[metric.key]));
    return filtered.slice(0, 10);
  }, [data, qualKey, minVal, metric]);

  const chartData = top.map((r) => ({ name: `${r.name} '${String(r.year).slice(2)}`, value: r[metric.key] })).reverse();

  return (
    <div>
      <PanelHead
        title="Leaderboards"
        desc="All-time single-season leaderboards across the full 1958–2023 franchise record."
        right={
          <div className="flex gap-1.5">
            <Pill active={ds === "batting"} onClick={() => switchDs("batting")}>Batting</Pill>
            <Pill active={ds === "pitching"} onClick={() => switchDs("pitching")}>Pitching</Pill>
          </div>
        }
      />
      <div className="flex gap-4 flex-wrap mb-5">
        <Field label="METRIC">
          <SelectBox value={metricKey} onChange={(e) => switchMetric(e.target.value)}
            options={metrics.map((m) => <option key={m.key} value={m.key}>{m.label}</option>)} />
        </Field>
        <Field label="MIN QUALIFIER">
          <SelectBox value={minVal} onChange={(e) => setMinVal(Number(e.target.value))}
            options={minOptions.map((v) => <option key={v} value={v}>{qualLabel} ≥ {v}</option>)} />
        </Field>
      </div>

      {top.length === 0 ? (
        <EmptyState>No qualifying seasons at this threshold.</EmptyState>
      ) : (
        <>
          <div className="border rounded p-3 mb-4" style={{ borderColor: "rgba(28,26,23,0.15)", background: WHITE }}>
            <ResponsiveContainer width="100%" height={320}>
              <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 20 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 10, fontFamily: "monospace" }} />
                <YAxis type="category" dataKey="name" width={130} tick={{ fontSize: 11 }} />
                <Tooltip formatter={(v) => metric.fmt(v)} />
                <Bar dataKey="value" fill={ORANGE} radius={[0, 3, 3, 0]} maxBarSize={22} />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div>
            {top.map((r, i) => (
              <RankRow key={i} rank={i + 1} name={r.name}
                meta={`${r.year} · Age ${r.age} · ${ds === "batting" ? r.pa + " PA" : r.ip.toFixed(1) + " IP"}`}
                value={metric.fmt(r[metric.key])} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ================= PLAYER ARC =================
function PlayerArc() {
  const [ds, setDs] = useState("batting");
  const data = ds === "batting" ? BATTING : PITCHING;
  const metrics = ds === "batting" ? BAT_METRICS : PIT_METRICS;
  const [metricKey, setMetricKey] = useState(metrics[0].key);
  const metric = metrics.find((m) => m.key === metricKey) || metrics[0];
  const [name, setName] = useState(ds === "batting" ? "Buster Posey" : "Logan Webb");

  function switchDs(next) {
    setDs(next);
    const nm = next === "batting" ? BAT_METRICS : PIT_METRICS;
    setMetricKey(nm[0].key);
    setName(next === "batting" ? "Buster Posey" : "Logan Webb");
  }

  const names = useMemo(() => uniqueNames(data), [data]);
  const rows = useMemo(
    () => data.filter((r) => r.name === name).sort((a, b) => a.year - b.year),
    [data, name]
  );
  const best = rows.length
    ? rows.reduce((a, b) => ((metric.asc ? b[metric.key] < a[metric.key] : b[metric.key] > a[metric.key]) ? b : a))
    : null;

  return (
    <div>
      <PanelHead
        title="Player Arc"
        desc="Track a single player's stat across every season they played for San Francisco."
        right={
          <div className="flex gap-1.5">
            <Pill active={ds === "batting"} onClick={() => switchDs("batting")}>Batting</Pill>
            <Pill active={ds === "pitching"} onClick={() => switchDs("pitching")}>Pitching</Pill>
          </div>
        }
      />
      <div className="flex gap-4 flex-wrap mb-5">
        <Field label="PLAYER">
          <input
            list="player-names"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Buster Posey"
            className="text-sm px-2.5 py-1.5 rounded border-2 min-w-[220px]"
            style={{ borderColor: INK }}
          />
          <datalist id="player-names">
            {names.map((n) => <option key={n} value={n} />)}
          </datalist>
        </Field>
        <Field label="METRIC">
          <SelectBox value={metricKey} onChange={(e) => setMetricKey(e.target.value)}
            options={metrics.map((m) => <option key={m.key} value={m.key}>{m.label}</option>)} />
        </Field>
      </div>

      {rows.length === 0 ? (
        <EmptyState>{name ? "No matching player — check the spelling." : "Start typing a player name above."}</EmptyState>
      ) : (
        <>
          <div className="border rounded p-3 mb-4" style={{ borderColor: "rgba(28,26,23,0.15)", background: WHITE }}>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={rows} margin={{ left: 10, right: 20 }}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="year" tick={{ fontSize: 10, fontFamily: "monospace" }} />
                <YAxis tick={{ fontSize: 10, fontFamily: "monospace" }} />
                <Tooltip formatter={(v) => metric.fmt(v)} />
                <Line type="monotone" dataKey={metric.key} stroke={ORANGE} strokeWidth={2.5}
                  dot={{ fill: INK, r: 4 }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <RankRow rank="" name={`Giants tenure: ${rows[0].year}–${rows[rows.length - 1].year} (${rows.length} seasons)`}
            value={`Peak: ${best.year}`} />
          <RankRow rank="" name={`Best ${metric.label}`} value={metric.fmt(best[metric.key])} />
        </>
      )}
    </div>
  );
}

// ================= ERAS (DECADES) =================
function Eras() {
  const [ds, setDs] = useState("batting");
  const data = ds === "batting" ? BATTING : PITCHING;

  const decadeData = useMemo(() => {
    const buckets = {};
    data.forEach((r) => {
      const d = `${Math.floor(r.year / 10) * 10}s`;
      if (!buckets[d]) buckets[d] = { h: 0, ab: 0, bb: 0, tb: 0, er: 0, ip: 0, players: new Set() };
      const b = buckets[d];
      b.players.add(r.name);
      if (ds === "batting") {
        b.h += r.h || 0;
        b.ab += r.ab || 0;
        b.bb += r.bb || 0;
        b.tb += (r.slg || 0) * (r.ab || 0); // TB = SLG * AB exactly by definition
      } else {
        b.er += ((r.era || 0) * (r.ip || 0)) / 9;
        b.ip += r.ip || 0;
      }
    });

    return Object.keys(buckets).sort().map((d) => {
      const b = buckets[d];
      let value;
      if (ds === "batting") {
        const obpApprox = b.ab + b.bb > 0 ? (b.h + b.bb) / (b.ab + b.bb) : 0;
        const slg = b.ab > 0 ? b.tb / b.ab : 0;
        value = obpApprox + slg;
      } else {
        value = b.ip > 0 ? (9 * b.er) / b.ip : 0;
      }
      return { decade: d, value, players: b.players.size };
    });
  }, [data, ds]);

  return (
    <div>
      <PanelHead
        title="Eras"
        desc="Team-wide performance by decade — every Giants season, aggregated."
        right={
          <div className="flex gap-1.5">
            <Pill active={ds === "batting"} onClick={() => setDs("batting")}>Batting</Pill>
            <Pill active={ds === "pitching"} onClick={() => setDs("pitching")}>Pitching</Pill>
          </div>
        }
      />
      <div className="text-[11px] font-mono mb-3" style={{ color: "#8a8374" }}>
        {ds === "batting"
          ? "Team OPS (OBP approximated from hits+walks, since HBP/SF weren't kept in this trimmed dataset)"
          : "Team ERA"}
      </div>
      <div className="border rounded p-3 mb-4" style={{ borderColor: "rgba(28,26,23,0.15)", background: WHITE }}>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={decadeData} margin={{ left: 10, right: 20 }}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="decade" tick={{ fontSize: 11 }} />
            <YAxis tick={{ fontSize: 10, fontFamily: "monospace" }} domain={["auto", "auto"]} />
            <Tooltip formatter={(v) => v.toFixed(ds === "batting" ? 3 : 2)} />
            <Bar dataKey="value" fill={ds === "batting" ? FOREST : INK} radius={[3, 3, 0, 0]} maxBarSize={46} />
          </BarChart>
        </ResponsiveContainer>
      </div>
      <div>
        {decadeData.map((d) => (
          <RankRow key={d.decade} rank={d.decade} name={`${d.players} players`}
            value={d.value.toFixed(ds === "batting" ? 3 : 2)} />
        ))}
      </div>
    </div>
  );
}

// ================= COMPARE =================
function Compare() {
  const [ds, setDs] = useState("batting");
  const data = ds === "batting" ? BATTING : PITCHING;
  const metrics = ds === "batting" ? BAT_METRICS : PIT_METRICS;
  const [metricKey, setMetricKey] = useState(metrics[0].key);
  const metric = metrics.find((m) => m.key === metricKey) || metrics[0];
  const [selected, setSelected] = useState([]);
  const [input, setInput] = useState("");

  const names = useMemo(() => uniqueNames(data), [data]);

  function switchDs(next) {
    setDs(next);
    const nm = next === "batting" ? BAT_METRICS : PIT_METRICS;
    setMetricKey(nm[0].key);
    setSelected([]);
    setInput("");
  }

  function addPlayer(name) {
    if (name && names.includes(name) && !selected.includes(name) && selected.length < 3) {
      setSelected([...selected, name]);
      setInput("");
    }
  }

  const chartData = useMemo(() => {
    const perPlayer = selected.map((name) => data.filter((r) => r.name === name).sort((a, b) => a.year - b.year));
    const years = Array.from(new Set(perPlayer.flat().map((r) => r.year))).sort((a, b) => a - b);
    return years.map((year) => {
      const point = { year };
      selected.forEach((name, i) => {
        const row = perPlayer[i].find((r) => r.year === year);
        point[name] = row ? row[metric.key] : null;
      });
      return point;
    });
  }, [selected, data, metric]);

  return (
    <div>
      <PanelHead
        title="Compare"
        desc="Overlay up to 3 players on the same stat, season by season."
        right={
          <div className="flex gap-1.5">
            <Pill active={ds === "batting"} onClick={() => switchDs("batting")}>Batting</Pill>
            <Pill active={ds === "pitching"} onClick={() => switchDs("pitching")}>Pitching</Pill>
          </div>
        }
      />
      <div className="flex gap-4 flex-wrap mb-3">
        <Field label="ADD PLAYER (press Enter)">
          <input
            list="compare-names"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") addPlayer(input.trim()); }}
            placeholder="Type a name, press Enter"
            className="text-sm px-2.5 py-1.5 rounded border-2 min-w-[220px]"
            style={{ borderColor: INK }}
          />
          <datalist id="compare-names">
            {names.map((n) => <option key={n} value={n} />)}
          </datalist>
        </Field>
        <Field label="METRIC">
          <SelectBox value={metricKey} onChange={(e) => setMetricKey(e.target.value)}
            options={metrics.map((m) => <option key={m.key} value={m.key}>{m.label}</option>)} />
        </Field>
      </div>
      <div className="flex gap-2 flex-wrap mb-4">
        {selected.map((name, i) => (
          <div key={name} className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold text-white"
            style={{ background: COMPARE_COLORS[i % COMPARE_COLORS.length] }}>
            {name}
            <button onClick={() => setSelected(selected.filter((n) => n !== name))}
              className="leading-none opacity-80 hover:opacity-100">&times;</button>
          </div>
        ))}
      </div>
      <div className="border rounded p-3" style={{ borderColor: "rgba(28,26,23,0.15)", background: WHITE }}>
        {selected.length === 0 ? (
          <EmptyState>Add a player above to start comparing.</EmptyState>
        ) : (
          <ResponsiveContainer width="100%" height={320}>
            <LineChart data={chartData} margin={{ left: 10, right: 20 }}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="year" tick={{ fontSize: 10, fontFamily: "monospace" }} />
              <YAxis tick={{ fontSize: 10, fontFamily: "monospace" }} />
              <Tooltip formatter={(v) => (v == null ? "—" : metric.fmt(v))} />
              <Legend wrapperStyle={{ fontSize: 12 }} />
              {selected.map((name, i) => (
                <Line key={name} type="monotone" dataKey={name} stroke={COMPARE_COLORS[i % COMPARE_COLORS.length]}
                  strokeWidth={2.5} connectNulls dot={{ r: 4 }} />
              ))}
            </LineChart>
          </ResponsiveContainer>
        )}
      </div>
    </div>
  );
}

// ================= FUN FACTS HEADER =================
function useFacts() {
  return useMemo(() => {
    const eligBat = BATTING.filter((r) => r.pa >= 300);
    const bestOps = eligBat.reduce((a, b) => (b.opsplus > a.opsplus ? b : a));
    const eligPit = PITCHING.filter((r) => r.ip >= 100);
    const bestEra = eligPit.reduce((a, b) => (b.era < a.era ? b : a));
    return { bestOps, bestEra };
  }, []);
}

